-- 强制播放 fade in:
---@param opNewStartTime_ number | nil
function IdolLive3D_FullScreenFXV2:StartFadeIn( opNewStartTime_ )
    if self.isInit ~= true then 
        return
    end 
    -- 整理时长:
    if type(opNewStartTime_) ~= "number" then 
        opNewStartTime_ = self.opStartTime
    end 
    opNewStartTime_ = Mathf.Min( Mathf.Max( opNewStartTime_, 0.0 ), self.opStartTime) -- [0,self.opStartTime]; 超过这个时长是无意义的;

    -- 只在最苛刻的条件下起效:
    if self.targetType == TargetType.ToHide then 
        if self.state == IdolLive3D_States.FullScreenFXState.Hide then 

            -- 正常的第一帧:
            self.lastUsedOpStartTime = opNewStartTime_ -- 覆写 时长
            Events.Broadcast( IdolLive3D_States.EventShowUIFullPanel, true, self.lastUsedOpStartTime, self.color ) -- ui 全屏
            self.state = IdolLive3D_States.FullScreenFXState.FadeIn
            self.targetType = TargetType.ToShow
            self.fadeInStartTime = Time.time
            self:_TrySetActive( self.opTF, true )
            return
        end 
    end 
    printError("无效的 FadeIn 调用 (暂时)")
end



---@param opNewStartTime_ number | nil
function IdolLive3D_FullScreenFXV2:StartFadeOut( edNewEndTime_ )
    if self.isInit ~= true then 
        return
    end 
    -- 整理时长:
    if type(edNewEndTime_) ~= "number" then 
        edNewEndTime_ = self.edEndTime
    end 
    edNewEndTime_ = Mathf.Min( Mathf.Max( edNewEndTime_, 0.0 ), self.edEndTime) -- [0,self.edEndTime]; 超过这个时长是无意义的;


    -- 只在最苛刻的条件下起效:
    if self.targetType == TargetType.ToShow then 
        if self.state == IdolLive3D_States.FullScreenFXState.Show then 

            -- 正常的第一帧:
            self.lastUsedEdStartTime = edNewEndTime_
            Events.Broadcast( IdolLive3D_States.EventShowUIFullPanel, false, self.lastUsedEdStartTime, self.color ) -- ui 全屏
            self.state = IdolLive3D_States.FullScreenFXState.FadeOut
            self.targetType = TargetType.ToHide
            self.fadeOutStartTime = Time.time    
            self:_TrySetActive( self.opTF, false )
            self:_TrySetActive( self.edTF, true )
            return
        end 
    end 
    printError("无效的 FadeOut 调用 (暂时)")
end



-- 协程
---@param opStartTime_ number | nil
function IdolLive3D_FullScreenFXV2:FadeIn( opStartTime_ )
    self:StartFadeIn(opStartTime_)
    cs_coroutine.yield_return( self:WaitTargetState( IdolLive3D_States.FullScreenFXState.Show ) )
end


-- 协程
---@param opStartTime_ number | nil
function IdolLive3D_FullScreenFXV2:FadeOut( edNewEndTime_ )
    self:StartFadeOut(edNewEndTime_)
    cs_coroutine.yield_return( self:WaitTargetState( IdolLive3D_States.FullScreenFXState.Hide ) )
end




-- 协程
function IdolLive3D_FullScreenFXV2:WaitTargetState( tgtState_ )
    local isWaited = false
    for i=0, 500 do 
        if self.state == tgtState_ then 
            isWaited = true
            break
        end 
        coroutine.yield(Yielders.EndOfFrame)
    end
    if isWaited ~= true then 
        printError("始终没等到; 参数 tgtState_ = " .. tostring(tgtState_))
    end 
end



